package org.animallink.incident.api;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class IncidentExceptionHandler { @ExceptionHandler(EventController.NotFound.class) ResponseEntity<?> n(Exception e){return ResponseEntity.status(404).body(new Error("RESOURCE_NOT_FOUND",e.getMessage()));}@ExceptionHandler(EventController.Unauthorized.class) ResponseEntity<?> u(Exception e){return ResponseEntity.status(401).body(new Error("UNAUTHORIZED",e.getMessage()));}@ExceptionHandler(EventController.Forbidden.class) ResponseEntity<?> f(Exception e){return ResponseEntity.status(403).body(new Error("FORBIDDEN",e.getMessage()));}@ExceptionHandler(EventController.Conflict.class) ResponseEntity<?> c(Exception e){return ResponseEntity.status(409).body(new Error("STATE_CONFLICT",e.getMessage()));}@ExceptionHandler(EventController.Dependency.class) ResponseEntity<?> d(Exception e){return ResponseEntity.status(503).body(new Error("DEPENDENCY_UNAVAILABLE",e.getMessage()));}@ExceptionHandler(Exception.class) ResponseEntity<?> b(Exception e){return ResponseEntity.badRequest().body(new Error("INVALID_REQUEST",e.getMessage()));} record Error(String code,String message){} }
